//#region ../send/frontend/src/apps/send/setup.js
function setupApp(app, telemetryAllowed = false) {
	const pinia = getSharedPinia();
	app.use(VueQueryPlugin);
	app.use(pinia);
	app.use(Gt);
	app.use(posthog_default);
	app.use(instance);
	setPosthogConsent(telemetryAllowed);
}
function mountApp(app, nodeName) {
	const vfm = zo();
	app.use(vfm).mount(nodeName);
}
//#endregion
//#region src/apps/extension.js
var app = createApp(ExtensionPage_default);
initSentry(app);
setupApp(app);
mountApp(app, "#extension-page");
//#endregion
